import { Component, createMemo, For, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CheckBox } from "#core/ui-next/components/check-box.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { AgeIcon } from "#core/ui-next/screens/create-game/age-icon.jsx";
import { useAgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { AttributeIcon } from "#core/ui-next/screens/create-game/attribute-icon.jsx";
import { CivInfo } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { useRecommendedChoiceModelContext } from "#core/ui-next/screens/create-game/recommended-choice-model.js";
import { TicketBox } from "#core/ui-next/screens/create-game/ticket-box.jsx";
import { TotIcon } from "#core/ui-next/screens/create-game/tot-icon.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import style from "./civ-card.scss?url";

export type CivCardProps = CivInfo & {
	class?: string;
	isSelected: boolean;
	isApexAgeSelected: boolean;
	leaderIcon: string;
	isRecommended: boolean;
	isUnlocks?: boolean;
	isCivSelect?: boolean;
	showAllUnlocks?: boolean;
	isCurrentCiv?: boolean;
	onSelect: () => void;
};

const CivCardComponent: Component<CivCardProps> = (props) => {
	const ageContext = useAgeSelectModelContext();
	// Only grab the recommendation model for recommended civs
	// eslint-disable-next-line solid/reactivity
	const choiceContext = !props.isRecommended ? undefined : useRecommendedChoiceModelContext();
	const activeAbility = createMemo(
		() =>
			props.perAgeAbilities.find((a) => a.age == ageContext.selectedAge.type) ??
			props.perAgeAbilities.find((a) => !a.age),
	);

	const activeRecommendation = createMemo(() => {
		if (!props.isRecommended || !choiceContext) {
			return undefined;
		}

		return choiceContext.forLeader().get(props.civID);
	});

	const isInGame = UI.isInGame();
	const isSmallScreen = useIsSmallScreen();

	const isChecked = createMemo(
		() => (!isInGame && props.isSelected) || (isInGame && (props.isCurrentCiv || props.isPreviousCiv)),
	);
	const showTooltip = createMemo(() => {
		return (
			props.isCivSelect ||
			(props.isUnlocks && props.unlockedBy.length > 0) ||
			(!props.isUnlocks && props.isLocked && props.unlockedBy.length > 0 && isInGame)
		);
	});

	return (
		<>
			<Tooltip>
				<Tooltip.Trigger>
					<Activatable
						onActivate={props.onSelect}
						class={`create-game-civ-card img-unit-panelbox relative group ${props.class ?? ""}`}
						classList={{ "mt-6": props.isRecommended }}
					>
						<div
							class="flex flex-col absolute inset-x-0\.5 inset-y-1"
							classList={{ "bg-contain": !isMobile(), "bg-cover bg-no-repeat": isMobile() }}
							style={{ "background-image": `url('blp:${props.bgImage}')` }}
						>
							<div class="create-game-civ-card-info flex-auto mt-16 relative">
								<div class="absolute flex create-game-civ-card-gradient -top-8 left-1\/2" />
								<div
									class="absolute inset-0 flex flex-col items-center justify-end"
									classList={{ "mb-10": !isMobile(), "mb-16": isMobile() }}
								>
									<Icon
										class="create-game-civ-card-info-icon"
										name={`url('${props.icon ?? ""}')`}
										isUrl={true}
									/>
									<Header
										class={`ml-3 uppercase font-black create-game-civ-card-text-gradient text-center ${isSmallScreen() && !isMobile() ? "text-sm" : "text-lg"}`}
									>
										{props.name}
									</Header>
								</div>
							</div>

							<div class="create-game-civ-card-icon-area relative">
								<div class="create-game-civ-card-icon-gradient absolute top-0 left-0 right-0 bottom-7" />
								<div
									class="absolute inset-0 bottom-10 flex flex-row items-center justify-center"
									classList={{ "pt-1": !isMobile(), "h-full": isMobile() }}
								>
									<div
										class="flex flex-row items-center gap-1"
										classList={{ "ml-4": !isMobile(), "mr-4": isMobile() }}
									>
										<For each={props.traits}>
											{(attribute) => (
												<div class="create-game-civ-card-icon-container flex items-center justify-center">
													<AttributeIcon
														class="create-game-civ-card-icon-attribute"
														attribute={attribute}
													/>
												</div>
											)}
										</For>
									</div>
									<Show when={!isMobile()}>
										<div class="flex-1" />
									</Show>
									<div
										class="flex flex-row items-center gap-1"
										classList={{ "mr-4": !isMobile(), "ml-4": isMobile() }}
									>
										<div class="create-game-civ-card-framed-icon-container flex items-center justify-center">
											<AgeIcon
												ageId={props.apexAge}
												class="create-game-civ-card-icon-age"
												framedIcons={true}
											/>
										</div>
										<div class="create-game-civ-card-framed-icon-container flex items-center justify-center">
											<TotIcon
												isApexAge={props.isApexAgeSelected}
												class="create-game-civ-card-icon-tot"
											/>
										</div>
									</div>
								</div>
								<Show when={isMobile()}>
									<div class="create-game-civ-card-inner-filigree absolute -top-1 self-center rotate-180" />
								</Show>
								<div class="create-game-civ-card-inner-filigree absolute -bottom-1\.5 self-center" />
							</div>
							<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
							<Show when={props.isLocked}>
								<div class="create-game-civ-card-disabled-bg absolute inset-0" />
								<div class="create-game-civ-card-locked-tag absolute -left-1\.5 top-1">
									<Icon
										class="size-8 mb-1 mr-3"
										name="url('blp:icon_lock')"
										isUrl={true}
									/>
								</div>
							</Show>

							<Show when={props.isRecommended}>
								<div class="flex flex-row self-center -top-3\.5 absolute">
									<div
										class="create-game-civ-card-top-filigree"
										classList={{ "opacity-60": props.isLocked }}
									/>
									<div
										class="create-game-civ-card-top-filigree -scale-x-100 ml-16"
										classList={{ "opacity-60": props.isLocked }}
									/>
								</div>

								<div class="flex flex-col absolute -top-9 left-0 right-0 items-center justify-center">
									<div
										class="size-20 relative"
										classList={{ "opacity-60": props.isLocked }}
									>
										<div class="create-game-civ-card-laurels absolute inset-0" />
										<div class="absolute inset-0 flex items-center justify-center pb-2">
											<div class="create-game-civ-card-leader-hex" />
										</div>
										<div class="absolute inset-0 flex items-center justify-center pb-2">
											<Icon
												name={props.leaderIcon}
												class="create-game-civ-card-leader"
											/>
										</div>
									</div>
								</div>
							</Show>

							<Show when={isChecked()}>
								<div class="absolute -left-2 top-4">
									<div
										class="flex flex-row items-start justify-start relative"
										style={{
											"border-image-source": `url('blp:tag_equipped.png')`,
											"border-image-slice": "1 6 1 1 fill",
											"border-image-repeat": "stretch",
											width: Layout.pixels(54),
											height: Layout.pixels(43),
										}}
									>
										<div
											class="img-icon-checkmark size-8 absolute mt-0\.5 ml-0\.5"
											style={{
												// eslint-disable-next-line solid/style-prop
												"fxs-background-image-tint": "black",
											}}
										/>
									</div>
								</div>
							</Show>
						</div>
					</Activatable>
				</Tooltip.Trigger>
				<Show when={showTooltip()}>
					<Tooltip.Content>
						<Tooltip.Frame class="flex flex-col relative w-128">
							<Show when={props.isCivSelect}>
								<div class="flex flex-row flex-wrap items-center justify-start">
									<For each={props.traits}>
										{(attribute) => (
											<div class="flex flex-row items-center justify-start">
												<div class="create-game-civ-card-tooltip-icon-container flex items-center justify-center mx-1">
													<AttributeIcon
														class="size-8"
														attribute={attribute}
													/>
												</div>

												<div class="uppercase">
													<L10n.Compose text={attribute} />
												</div>
											</div>
										)}
									</For>
								</div>

								<TicketBox class="px-6 pt-4 pb-6">
									<div class="uppercase text-secondary-1 text-sm font-title">
										<L10n.Compose text={activeAbility()?.abilityTitle ?? ""} />
									</div>
									<div class="uppercase text-accent-2 text-sm font-body">
										<L10n.Compose text="LOC_UI_CREATE_GAME_CIVILIZATION_ABILITY" />
									</div>
									<L10n.Stylize
										class="create-game-markup tight"
										text={activeAbility()?.abilityText ?? ""}
									/>
								</TicketBox>

								<Show when={props.isRecommended}>
									<TicketBox class="flex flex-row items-center px-6 pt-4 pb-6">
										<Icon
											name={props.leaderIcon}
											class="size-13"
										/>
										<L10n.Stylize
											class="flex-auto create-game-markup tight"
											text={activeRecommendation()?.reason ?? ""}
										/>
									</TicketBox>
								</Show>
							</Show>
							<Show when={props.isUnlocks && props.unlockedBy.length > 0}>
								<div class="text-secondary uppercase self-center text-xl font-title mt-3">
									<L10n.Compose
										text="LOC_LEGACIES_UNLOCKS_TOOLTIP_TITLE"
										args={[props.name]}
									/>
								</div>
								<TicketBox class="flex flex-col justify-start px-6 pt-4 pb-6">
									<div class="flex flex-row w-full items-center">
										<div class="flex flex-col">
											<Show when={props.isLocked}>
												<L10n.Stylize
													class="create-game-markup"
													text="LOC_LEGACIES_UNLOCKS_PRIMARY_UNLOCK_EXPLANATION"
													args={[props.name, props.ageName]}
												/>
												<div
													class={`h-1 w-full bg-cover mb-2`}
													style={{ "background-image": "url(blp:shell_line-divider)" }}
												/>
											</Show>
										</div>
									</div>

									<Show
										when={
											props.unlockedBy.length > 1 &&
											props.unlockedBy[0].isUnlocked &&
											!props.showAllUnlocks
										}
									>
										<div class="flex flex-row flex-wrap here">
											<CheckBox
												class={isMobile() ? "size-10" : "size-6"}
												isChecked={props.unlockedBy[0].isUnlocked}
												disabled={true}
											/>
											<L10n.Stylize
												class="flex-auto create-game-markup tight"
												text={props.unlockedBy[0].text}
											/>
										</div>
									</Show>
									<Show when={!props.unlockedBy[0].isUnlocked || props.showAllUnlocks}>
										<For each={props.unlockedBy}>
											{(unlock) => (
												<Show when={unlock.isGameplayUnlock}>
													<div class="flex flex-row flex-wrap here-1">
														<CheckBox
															class={isMobile() ? "size-10" : "size-6"}
															isChecked={unlock.isUnlocked}
															disabled={true}
														/>
														<L10n.Stylize
															class="flex-auto create-game-markup tight"
															text={unlock.text}
														/>
													</div>
												</Show>
											)}
										</For>
									</Show>
								</TicketBox>
								<Show when={props.showAllUnlocks}>
									<TicketBox class="flex flex-col justify-start px-6 pt-4 pb-6 mt-3">
										<div class="text-secondary uppercase font-title text-xl mb-2 text-center">
											<L10n.Compose text="LOC_LEGACIES_UNLOCKS_ADDITIONAL" />
										</div>
										<For each={props.unlockedBy}>
											{(unlock) => (
												<Show when={!unlock.isGameplayUnlock}>
													<div class="flex flex-row flex-wrap w-full">
														<CheckBox
															class={isMobile() ? "size-10" : "size-6"}
															isChecked={unlock.isUnlocked}
														/>
														<L10n.Stylize
															class="flex-auto create-game-markup tight"
															text={unlock.text}
														/>
													</div>
												</Show>
											)}
										</For>
									</TicketBox>
								</Show>
							</Show>
							<Show when={!props.isUnlocks && props.isLocked && props.unlockedBy.length > 0 && isInGame}>
								<TicketBox class="flex flex-col items-start justify-start px-6 pt-4 pb-6">
									<For each={props.unlockedBy.filter((u) => !u.isUnlocked)}>
										{(unlock) => (
											<L10n.Stylize
												class="flex-auto create-game-markup tight"
												text={unlock.text}
											/>
										)}
									</For>
								</TicketBox>
							</Show>
						</Tooltip.Frame>
					</Tooltip.Content>
				</Show>
			</Tooltip>
		</>
	);
};

export const CivCard = ComponentRegistry.register({
	name: "CivCard",
	createInstance: CivCardComponent,
	styles: [style],
});
